// This file is generated by AI.

// 设置对话框: 左侧分类导航 + 右侧设置项 (编辑 / 引擎 / 模板 / 关于)。
//
// 使用自绘模态层 (position: fixed + 点击遮罩关闭), 不依赖弹层类 UI 组件,
// 避免在 WebView 中弹层定位/动画异常导致的白屏与闪动问题。
// 主题切换统一由标题栏的按钮完成; 预览开关在预览面板工具栏上。

import { openUrl } from '@tauri-apps/plugin-opener';
import { Button, Input, Switch } from '@fluentui/react-components';
import { DocumentRegular, GlobeRegular, PersonRegular } from '@fluentui/react-icons';
import { useEffect, useState } from 'react';

import { useAppStore, type SettingsCategory } from '../state/store';
import type { Settings } from '../lib/settings';
import { AppDialog } from './AppDialog';
import { EngineManager } from './EngineManager';
import { TemplateManager } from './TemplateManager';

const CATEGORIES: { id: SettingsCategory; label: string }[] = [
  { id: 'editor', label: '编辑' },
  { id: 'engine', label: '引擎' },
  { id: 'template', label: '模板' },
  { id: 'about', label: '关于' },
];

// 关于页链接 (仓库 / 作者 / 许可证)
const ABOUT_LINKS: { label: string; icon: JSX.Element; url: string }[] = [
  { label: 'GitHub 仓库', icon: <GlobeRegular />, url: 'https://github.com/fltLi/webgal-lsp' },
  { label: '作者 fltLi', icon: <PersonRegular />, url: 'https://github.com/fltLi' },
  { label: '许可证 MPL-2.0', icon: <DocumentRegular />, url: 'https://www.mozilla.org/MPL/2.0/' },
];

export function SettingsDialog() {
  const settingsOpen = useAppStore((s) => s.settingsOpen);
  const setSettingsOpen = useAppStore((s) => s.setSettingsOpen);
  const settings = useAppStore((s) => s.settings);
  const updateSettings = useAppStore((s) => s.updateSettings);
  const storeCategory = useAppStore((s) => s.settingsCategory);
  const [category, setCategory] = useState<SettingsCategory>('editor');

  // 打开设置时定位到 store 指定的分类 (如"项目"页的"管理模板"入口)
  useEffect(() => {
    if (settingsOpen) setCategory(storeCategory);
  }, [settingsOpen, storeCategory]);

  if (!settingsOpen) return null;

  const updateNumber = (key: 'editorFontSize', raw: string, min: number, max: number) => {
    const n = Number(raw);
    if (!Number.isFinite(n)) return;
    updateSettings({ [key]: Math.min(max, Math.max(min, Math.round(n))) } as Partial<Settings>);
  };

  return (
    <AppDialog
      title="设置"
      size="medium"
      height={560}
      flush
      closeOnBackdrop
      onClose={() => setSettingsOpen(false)}
      footer={
        <Button appearance="primary" onClick={() => setSettingsOpen(false)}>
          关闭
        </Button>
      }
    >
      <div className="settings-layout">
        <nav className="settings-nav">
          {CATEGORIES.map((c) => (
            <button
              key={c.id}
              className={`settings-nav-item${category === c.id ? ' active' : ''}`}
              onClick={() => setCategory(c.id)}
            >
              {c.label}
            </button>
          ))}
        </nav>

        <div className="settings-content">
          {category === 'editor' && (
            <div className="settings-group">
              <h3 className="settings-group-title">编辑器</h3>

              <div className="settings-field">
                <Switch
                  checked={settings.autoSave}
                  onChange={(_, data) => updateSettings({ autoSave: data.checked })}
                  label="自动保存"
                />
              </div>

              <div className="settings-field">
                <span className="settings-label">字体</span>
                <Input
                  value={settings.editorFontFamily}
                  placeholder="FiraCode, SourceHanSans, Consolas, monospace"
                  onChange={(_, data) => updateSettings({ editorFontFamily: data.value })}
                />
              </div>

              <div className="settings-field settings-field-inline">
                <span className="settings-label">字号</span>
                <Input
                  type="number"
                  min={8}
                  max={48}
                  value={String(settings.editorFontSize)}
                  onChange={(_, data) => updateNumber('editorFontSize', data.value, 8, 48)}
                />
              </div>

              <div className="settings-field">
                <Switch
                  checked={settings.editorWordWrap}
                  onChange={(_, data) => updateSettings({ editorWordWrap: data.checked })}
                  label="自动换行"
                />
              </div>

              <div className="settings-field">
                <Switch
                  checked={settings.editorMinimap}
                  onChange={(_, data) => updateSettings({ editorMinimap: data.checked })}
                  label="代码缩略图"
                />
              </div>
            </div>
          )}
          {category === 'engine' && (
            <div className="settings-group">
              <EngineManager />
            </div>
          )}
          {category === 'template' && (
            <div className="settings-group">
              <TemplateManager />
            </div>
          )}
          {category === 'about' && (
            <div className="settings-about">
              <section className="settings-about-intro">
                <img className="settings-about-mark" src="/ink-icon.svg" alt="" draggable={false} />
                <div>
                  <h3 className="settings-about-title">WebGAL Ink</h3>
                  <p className="settings-about-description">WebGAL 视觉小说代码编辑器</p>
                </div>
              </section>

              <section className="settings-about-section">
                <div className="settings-about-section-head">
                  <h4>资源与支持</h4>
                </div>
                <div className="settings-link-list">
                  {ABOUT_LINKS.map((link) => (
                    <button key={link.label} className="settings-link-item" onClick={() => void openUrl(link.url)}>
                      <span className="settings-link-icon">{link.icon}</span>
                      <span className="settings-link-copy">
                        <strong>{link.label}</strong>
                        <small>{link.url.replace('https://', '')}</small>
                      </span>
                    </button>
                  ))}
                </div>
              </section>

              <footer className="settings-about-footer">
                <span>© 2026 fltLi</span>
                <span>MPL-2.0</span>
              </footer>
            </div>
          )}
        </div>
      </div>
    </AppDialog>
  );
}
